INSERT INTO books (title, author, publisher, release_year, genre, summary, comment, cover_r2_key, sort_order) VALUES
('Metaverse Dream', 'Assouline (editorial)', 'Assouline', NULL, 'Libro de mesa / lifestyle',
 'Un libro de mesa de gran formato sobre el metaverso y los mundos virtuales, con un código QR en relieve metálico en la portada — Assouline en su tono más irónico: lo más digital posible, hecho un objeto físico de lujo.',
 'Regalo de un familiar. Assouline es una editorial francesa de lujo fundada en 1994 en París por el matrimonio Prosper y Martine Assouline — el proyecto arrancó literalmente en el sótano de su departamento. Su primer libro, sobre el hotel La Colombe d''Or, salió ese mismo año; desde entonces han publicado más de 1,700 títulos sobre arte, diseño, moda, gastronomía y viajes, y son conocidos por convertir el libro de mesa en un objeto de lujo — por decisión propia, nunca han sacado una versión digital de sus libros.',
 'biblioteca/assouline-metaverse.webp', 90);

